internal static class Program{
 static int pass,fail;static BindingFlags flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
 static void Check(string n,Func<bool> f){try{if(!f())throw new Exception("condition false");Console.WriteLine("PASS "+n);pass++;}catch(Exception e){Console.WriteLine("FAIL "+n+": "+e.GetBaseException().Message);fail++;}}
 static bool Refuses(Action a){try{a();return false;}catch{return true;}}
 static void Set(object o,string n,object v){var t=o as Type;var f=(t??o.GetType()).GetField(n,flags);if(f!=null)f.SetValue(t==null?o:null,v);}
 static void Hook(NativeOrdinaryAcquisitionProbe p,string n,UnitEntityData actor,SaveInfo save=null,object manager=null,object game=null){var m=typeof(NativeOrdinaryAcquisitionProbe).GetNestedType("Hooks",flags).GetMethod(n,flags);var a=m.GetParameters().Select(x=> x.Name=="unit"?(object)actor:x.Name=="isChargen"?false:x.Name=="saveInfo"||x.Name=="save"?save:x.Name=="__instance"?(n=="SaveBefore"?game??Game.Instance:manager??Game.Instance.SaveManager):null).ToArray();m.Invoke(null,a);}
 static NativeOrdinaryAcquisitionProbe New(out UnitEntityData actor){Game.Instance=new Game();actor=new UnitEntityData();var a=actor;var p=new NativeOrdinaryAcquisitionProbe(()=>a);p.Install();Time.frameCount=1;return p;}
 static SaveInfo RequestSave(NativeOrdinaryAcquisitionProbe p,UnitEntityData a){var r=new SaveInfo{FileName=null,FolderName=null,HasFileOnDisk=false,IsActuallySaved=false};Hook(p,"CompletionBefore",a);Hook(p,"SaveBefore",a,r);Hook(p,"CompletionAfter",a);Time.frameCount=2;return r;}
 static NativeOrdinaryAcquisitionProbe CompletionProbe(out SaveInfo requested,out SaveInfo prepared){UnitEntityData a;var p=New(out a);requested=new SaveInfo{HasFileOnDisk=false,IsActuallySaved=false,FileName=null,FolderName=null};prepared=new SaveInfo();Set(p,"observedSave",prepared);Set(p,"requestedSave",requested);Set(p,"requestedName",requested.Name);Set(p,"completionEntries",1);Set(p,"completionExits",1);Set(p,"saveRequests",1);Set(p,"preparedWrites",1);return p;}
 static CompletionAdapter Adapter(NativeOrdinaryAcquisitionProbe p,SaveInfo r,SaveInfo s){var a=new CompletionAdapter{probe=p,ordinaryProbe=p,completion=p};a.persistence.LastCompletedSave=new NativeSaveCompletion(1,r,s,s.FolderName);return a;}
 static bool Run(CompletionAdapter a,string kind){return (bool)typeof(CompletionAdapter).GetMethod(kind,flags).Invoke(a,null);}
 static int Main(){
 Check("native request and prepared copy complete exact observer",()=>{UnitEntityData a;using(var p=New(out a)){var r=RequestSave(p,a);var s=new SaveInfo();Hook(p,"PreparedAfter",a,s);return p.Complete&&ReferenceEquals(p.ObservedSave,s)&&!ReferenceEquals(r,s)&&!r.HasFileOnDisk;}});
 Check("in-place preparation refuses wrong lifecycle",()=>{UnitEntityData a;using(var p=New(out a)){var r=RequestSave(p,a);r.FileName="Auto_1.zks";Hook(p,"PreparedAfter",a,r);return !p.Complete;}});
 foreach(var kind in new[]{"Ordinary","Manual","Progression"}){
  Check(kind+" accepts exact completed native clone",()=>{SaveInfo r,s;using(var p=CompletionProbe(out r,out s)){return Run(Adapter(p,r,s),kind);}});
  foreach(var mutation in new[]{"missing","request","written","sequence","path","count","authorization","world"}){var m=mutation;Check(kind+" refuses completion "+m,()=>{SaveInfo r,s;using(var p=CompletionProbe(out r,out s)){var a=Adapter(p,r,s);if(m=="missing")a.persistence.LastCompletedSave=null;if(m=="request")a.persistence.LastCompletedSave=new NativeSaveCompletion(1,new SaveInfo(),s,s.FolderName);if(m=="written")a.persistence.LastCompletedSave=new NativeSaveCompletion(1,r,new SaveInfo(),s.FolderName);if(m=="sequence")a.persistence.LastCompletedSave=new NativeSaveCompletion(2,r,s,s.FolderName);if(m=="path")a.persistence.LastCompletedSave=new NativeSaveCompletion(1,r,s,"foreign");if(m=="count")a.persistence.CompletedSaveCount=2;if(m=="authorization")a.authorization.AuthorizedWriteCount=0;if(m=="world")s.GameId="foreign";return Refuses(()=>Run(a,kind));}});}
  Check(kind+" waits while native worker is busy",()=>{SaveInfo r,s;using(var p=CompletionProbe(out r,out s)){var a=Adapter(p,r,s);a.busy=true;return !Run(a,kind);}});
 }
 foreach(var mutation in new[]{"name","leaf","category","not-levelup","same-object","foreign-manager","foreign-game","changed-request","before-exit","duplicate"}){var m=mutation;Check("observer refuses prepared "+m,()=>{UnitEntityData a;using(var p=New(out a)){SaveInfo r;if(m=="before-exit"){r=new SaveInfo();Hook(p,"CompletionBefore",a);Hook(p,"SaveBefore",a,r);}else r=RequestSave(p,a);var s=new SaveInfo();if(m=="name")s.Name="foreign";if(m=="leaf")s.FileName="Auto_2.zks";if(m=="category")s.Type=SaveInfo.SaveType.Manual;if(m=="not-levelup")s.IsAutoLevelupSave=false;if(m=="same-object"){r.FileName="Auto_1.zks";s=r;}if(m=="changed-request")r.Name="foreign";if(m=="foreign-game")Game.Instance=new Game();Hook(p,"PreparedAfter",a,s,m=="foreign-manager"?new SaveManager():null);if(m=="duplicate")Hook(p,"PreparedAfter",a,s);var refused=!p.Complete;if(m=="before-exit")Hook(p,"CompletionAfter",a);return refused;}});}
 Check("failed unpatch remains owned and retries",()=>{UnitEntityData a;var p=New(out a);Harmony12.HarmonyInstance.FailUnpatch=true;var refused=Refuses(()=>p.Dispose());var retained=typeof(NativeOrdinaryAcquisitionProbe).GetField("active",flags).GetValue(null)==p;Harmony12.HarmonyInstance.FailUnpatch=false;p.Dispose();return refused&&retained&&typeof(NativeOrdinaryAcquisitionProbe).GetField("active",flags).GetValue(null)==null;});
 Console.WriteLine("ORDINARY SAVE DESCRIPTOR PASS="+pass+" FAIL="+fail+"; actual production probe and completion predicate prefixes; metadata/Harmony/native objects substituted; no save archive or game calls.");return fail==0?0:1;
}}
